#!/usr/bin/env bash
# ============================================================================
#  灵犀官网 · 一体化部署脚本（站点内容已内嵌，无需上传任何文件）
#
#  用法：腾讯云控制台 → 云服务器 → 灵犀官网(lhins-p8119085) → 登录(网页终端)
#        粘贴下面【全部内容】→ 回车
#
#  说明：
#   · 不要粘贴带行号(1. 2. 3.)的内容，会被当成命令
#   · 本脚本幂等，可重复执行
#   · 不修改 SSH 端口，不会把你关在门外
# ============================================================================
set -uo pipefail

DOMAIN="lingxi-engine.com"
SITE_DIR="/opt/lingxi-site"
LOG="/var/log/lingxi-deploy.log"
B64="/root/lingxi-site.b64"
TGZ="/root/lingxi-site.tar.gz"

log() { echo "[$(date '+%H:%M:%S')] $*"; echo "[$(date '+%H:%M:%S')] $*" >> "$LOG" 2>/dev/null || true; }
die() { log "✗ $1"; log "日志: $LOG"; exit 1; }

log "===== 灵犀官网部署开始 ====="
log "域名: $DOMAIN  目录: $SITE_DIR"

# ---------- 0. 必须是 root ----------
if [ "$(id -u)" -ne 0 ]; then
  die "不是 root。腾讯云默认就是 root，直接跑即可"
fi

# ---------- 1. 端口预检（绝不覆盖已有服务）----------
log ""
log ">>> [1/8] 端口占用预检"
BUSY=""
for p in 80 443; do
  if ss -tln 2>/dev/null | awk '{print $4}' | grep -qE "[:.]${p}\$"; then
    BUSY="$BUSY $p"
  fi
done
if [ -n "$BUSY" ]; then
  log "✗ 端口已被占用:$BUSY"
  ss -tlnp 2>/dev/null | grep -E "[:.](80|443)\$" | sed 's/^/     /'
  log "   处置：a) systemctl stop <占用服务> 后重跑  b) 如需换端口请改脚本顶部 PORT"
  exit 2
fi
log "✓ 80/443 均空闲"

# ---------- 2. 系统更新 ----------
log ""
log ">>> [2/8] 系统更新"
export DEBIAN_FRONTEND=noninteractive
apt-get update -qq >/dev/null 2>&1 && log "  apt 索引已更新" || log "  ⚠️ apt update 失败（可忽略，继续）"

# ---------- 3. 安装依赖 ----------
log ""
log ">>> [3/8] 安装 nginx / certbot / fail2ban"
NEED=""
for c in nginx certbot curl; do
  command -v "$c" >/dev/null 2>&1 || NEED="$NEED $c"
done
if ! command -v fail2ban-client >/dev/null 2>&1; then
  NEED="$NEED fail2ban"
fi
if [ -n "$NEED" ]; then
  apt-get install -y -qq $NEED >/dev/null 2>&1
fi
systemctl enable --now nginx >/dev/null 2>&1
log "  nginx    = $(systemctl is-active nginx 2>/dev/null)"
log "  fail2ban = $(systemctl is-active fail2ban 2>/dev/null)"
log "  certbot  = $(command -v certbot || echo 未安装)"
[ "$(systemctl is-active nginx)" = "active" ] || die "nginx 启动失败"

# ---------- 3.5 鍐呭祵绔欑偣鏁版嵁锛堥娆¤繍琛岃嚜鍔ㄩ噴鏀撅級----------
if [ ! -s "$B64" ]; then
  cat > "$B64" <<'LINGXI_SITE_B64_EOF_7c3d'

LINGXI_SITE_B64_EOF_7c3d
fi

# ---------- 4. 释放站点文件（内嵌 base64）----------
log ""
log ">>> [4/8] 释放站点文件"
if [ ! -f "$B64" ]; then
  log "  ✗ 未找到内嵌数据文件 $B64"
  die "内嵌数据缺失，脚本可能被截断，请重新完整复制"
fi
base64 -d "$B64" > "$TGZ" 2>/dev/null || die "base64 解码失败（复制过程可能损坏）"
log "  解包 $(du -h "$TGZ" | cut -f1)"
rm -rf "$SITE_DIR"
mkdir -p "$SITE_DIR"
tar -xzf "$TGZ" -C "$SITE_DIR" --strip-components=1 2>/dev/null \
  || tar -xzf "$TGZ" -C "$SITE_DIR" 2>/dev/null \
  || die "tar 解包失败"
log "  站点文件："
ls -1 "$SITE_DIR" 2>/dev/null | sed 's/^/     /'
[ -f "$SITE_DIR/index.html" ] || die "index.html 未就位"
log "  ✓ index.html $(wc -c < "$SITE_DIR/index.html") 字节"

# ---------- 5. nginx 配置（先只开 80，证书签发后再上 443）----------
log ""
log ">>> [5/8] 生成 nginx 配置"
cat > /etc/nginx/conf.d/lingxi-site.conf <<'NGINXEOF'
server {
    listen 80;
    listen [::]:80;
    server_name lingxi-engine.com www.lingxi-engine.com;

    location ^~ /.well-known/acme-challenge/ {
        root /var/www/html;
        default_type "text/plain";
        allow all;
    }

    location / {
        root /opt/lingxi-site;
        index index.html;
        try_files $uri $uri/ /index.html;
    }

    location ~* \.(css|js|svg|png|jpg|jpeg|webp|ico|woff2?)$ {
        root /opt/lingxi-site;
        expires 7d;
        add_header Cache-Control "public, max-age=604800";
    }

    access_log /var/log/nginx/lingxi-access.log;
    error_log  /var/log/nginx/lingxi-error.log;
}
NGINXEOF
mkdir -p /var/www/html
if nginx -t 2>&1 | grep -q "syntax is ok"; then
  systemctl reload nginx 2>/dev/null || systemctl restart nginx
  log "  ✓ nginx 配置语法 OK，已生效（HTTP）"
else
  log "  ✗ nginx 配置有错："
  nginx -t 2>&1 | sed 's/^/     /'
  rm -f /etc/nginx/conf.d/lingxi-site.conf
  systemctl reload nginx 2>/dev/null
  die "已回滚到默认配置，请检查"
fi

# ---------- 6. fail2ban 防爆破 ----------
log ""
log ">>> [6/8] 配置 fail2ban"
if command -v fail2ban-client >/dev/null 2>&1; then
  mkdir -p /etc/fail2ban
  cat > /etc/fail2ban/jail.local <<'JEOF'
[DEFAULT]
bantime  = 1h
findtime = 10m
maxretry = 5

[sshd]
enabled  = true
port     = 22
logpath  = /var/log/auth.log
maxretry = 4
bantime  = 1h
JEOF
  systemctl restart fail2ban >/dev/null 2>&1
  log "  fail2ban = $(systemctl is-active fail2ban 2>/dev/null)"
else
  log "  ⚠️ fail2ban 未安装，跳过"
fi

# ---------- 7. HTTPS ----------
log ""
log ">>> [7/8] 申请 HTTPS 证书（Let's Encrypt）"
if [ -f "/etc/letsencrypt/live/$DOMAIN/fullchain.pem" ]; then
  log "  ✓ 证书已存在，跳过签发"
else
  certbot certonly --webroot -w /var/www/html \
    -d "$DOMAIN" -d "www.$DOMAIN" \
    --non-interactive --agree-tos --register-unsafely-without-email \
    --keep-until-expiring >/dev/null 2>&1

  if [ -f "/etc/letsencrypt/live/$DOMAIN/fullchain.pem" ]; then
    log "  ✓ 证书签发成功！切换到 HTTPS"
    cat > /etc/nginx/conf.d/lingxi-site.conf <<'FULLEOF'
server {
    listen 80;
    listen [::]:80;
    server_name lingxi-engine.com www.lingxi-engine.com;
    location ^~ /.well-known/acme-challenge/ { root /var/www/html; default_type "text/plain"; allow all; }
    location / { return 301 https://$host$request_uri; }
    access_log /var/log/nginx/lingxi-access.log;
    error_log  /var/log/nginx/lingxi-error.log;
}
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
    server_name lingxi-engine.com www.lingxi-engine.com;
    ssl_certificate     /etc/letsencrypt/live/lingxi-engine.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/lingxi-engine.com/privkey.pem;
    ssl_protocols       TLSv1.2 TLSv1.3;
    ssl_session_cache   shared:SSL:10m;
    ssl_session_timeout 14400m;
    add_header Strict-Transport-Security "max-age=31536000" always;
    location / {
        root /opt/lingxi-site;
        index index.html;
        try_files $uri $uri/ /index.html;
    }
    location ~* \.(css|js|svg|png|jpg|jpeg|webp|ico|woff2?)$ {
        root /opt/lingxi-site;
        expires 7d;
        add_header Cache-Control "public, max-age=604800";
    }
    access_log /var/log/nginx/lingxi-access.log;
    error_log  /var/log/nginx/lingxi-error.log;
}
FULLEOF
    if nginx -t 2>&1 | grep -q "syntax is ok"; then
      systemctl reload nginx 2>/dev/null
      log "  ✓ 443 已启用，80 自动 301 跳转 HTTPS"
    else
      log "  ✗ 完整配置语法错，保持 HTTP"
    fi
  else
    log "  ⚠️ 证书未签发。网站仍可 HTTP 访问"
    log "     常见原因：80 端口公网不可达 / DNS 未生效 / Let's Encrypt 频率超限"
  fi
fi
command -v certbot >/dev/null 2>&1 && systemctl enable certbot.timer >/dev/null 2>&1

# ---------- 8. 自检 ----------
log ""
log ">>> [8/8] 部署自检"
PASS=0; FAIL=0
chk() {
  if eval "$2" >/dev/null 2>&1; then
    echo "  ✓ $1"; PASS=$((PASS+1))
  else
    echo "  ✗ $1"; FAIL=$((FAIL+1))
  fi
}

chk "nginx 运行中"        "systemctl is-active --quiet nginx"
chk "首页存在"            "test -f $SITE_DIR/index.html"
chk "服务协议存在"        "test -f $SITE_DIR/terms.html"
chk "隐私政策存在"        "test -f $SITE_DIR/privacy.html"
chk "robots.txt 存在"    "test -f $SITE_DIR/robots.txt"
chk "本机 HTTP 80 响应"   "curl -s -o /dev/null -w '%{http_code}' -H 'Host: $DOMAIN' http://127.0.0.1/ | grep -qE '^(200|301|302)$'"
HAS443=$(ss -tln 2>/dev/null | awk '{print $4}' | grep -cE '[:.]443\$' || true)
if [ "$HAS443" -gt 0 ]; then
  chk "本机 HTTPS 443 响应" "curl -sk -o /dev/null -w '%{http_code}' -H 'Host: $DOMAIN' https://127.0.0.1/ | grep -qE '^(200|301|302)$'"
else
  echo "  - 本机 HTTPS 443 响应  (未启用，跳过)"; log "  (443 未启用)"
fi
if command -v fail2ban-client >/dev/null 2>&1; then
  chk "fail2ban 运行中"   "systemctl is-active --quiet fail2ban"
else
  echo "  - fail2ban (未安装，跳过)"
fi
if [ -f "/etc/letsencrypt/live/$DOMAIN/fullchain.pem" ]; then
  chk "HTTPS 证书存在"    "test -f /etc/letsencrypt/live/$DOMAIN/fullchain.pem"
else
  echo "  - HTTPS 证书 (未签发，跳过)"
fi

echo ""
echo "  ---------- 响应码 ----------"
printf "  http  127.0.0.1 : %s\n" "$(curl -s -o /dev/null -w '%{http_code}' -H "Host: $DOMAIN" http://127.0.0.1/ 2>/dev/null || echo FAIL)"
printf "  https 127.0.0.1 : %s\n" "$(curl -sk -o /dev/null -w '%{http_code}' -H "Host: $DOMAIN" https://127.0.0.1/ 2>/dev/null || echo FAIL)"
printf "  http  公网域名   : %s\n" "$(curl -s -o /dev/null -w '%{http_code}' --max-time 12 "http://$DOMAIN/" 2>/dev/null || echo TIMEOUT)"
printf "  https 公网域名   : %s\n" "$(curl -sk -o /dev/null -w '%{http_code}' --max-time 12 "https://$DOMAIN/" 2>/dev/null || echo TIMEOUT)"

echo ""
echo "################################################"
log "自检结果: $PASS 通过 / $FAIL 失败"
log "完整日志: $LOG"
echo "################################################"
echo ""
if [ "$FAIL" -eq 0 ]; then
  echo "🎉 部署完成！浏览器打开:  https://$DOMAIN"
else
  echo "⚠️  有项目未通过，看上方 ✗ 行，或查 $LOG"
fi
